214		 * equal to the number of entries in the S/G list that we give to the
215		 * hypervisor.
216		 */
217		lb_offset = param.local_vaddr & (PAGE_SIZE - 1);
218		if (param.count == 0 ||
219		    param.count > U64_MAX - lb_offset - PAGE_SIZE + 1)
220			return -EINVAL;
